// The Daily Brief: what a person who knows the whole schedule would tell the team this morning.
// Everything here is calculated from the schedule (RunF9's recalculated dates, float and driving path),
// the project register (risks, issues, change items) and signals found in project correspondence.
// Nothing is generated by a language model, so the same schedule always gives the same brief and every
// line can be traced to an activity, a register item or a quoted passage. Pure: no database access.

import type { Activity, Relationship } from '@/lib/db'
import { CIVIL_PROJECT_TYPES } from '@/lib/planning/types'

export const BRIEF_LIST_LIMIT = 12
/** Open work with total float at or under this many work days is "about to become critical". */
export const NEAR_CRITICAL_DAYS = 10

export type RegisterKind = 'risk' | 'issue' | 'pco' | 'change_request' | 'change_order' | 'amendment'
export const REGISTER_KINDS: readonly RegisterKind[] = ['risk', 'issue', 'pco', 'change_request', 'change_order', 'amendment']
export const REGISTER_LABELS: Record<RegisterKind, string> = {
  risk: 'Risk', issue: 'Issue', pco: 'Potential change order (PCO)', change_request: 'Change request', change_order: 'Change order', amendment: 'Contract amendment',
}

export interface RegisterItem {
  id: string
  kind: RegisterKind
  title: string
  detail?: string | null
  status: 'open' | 'closed'
  owner?: string | null
  /** YYYY-MM-DD the item must be resolved by */
  dueDate?: string | null
  /** Work days of schedule impact the team expects (+ = later) */
  impactDays?: number | null
  /** Activity codes the item touches */
  activityCodes?: string[]
  sourceDocumentId?: string | null
  sourceQuote?: string | null
  createdAt: string
  createdByName?: string | null
}

export interface BriefRow {
  id: string
  code: string
  name: string
  /** The date the row is about (YYYY-MM-DD) */
  date: string | null
  float: number | null
  critical: boolean
  milestone: boolean
  /** Calendar days late against the brief date, where that is the point of the row */
  daysLate?: number
  note?: string
}

export interface BriefChange {
  what: string
  before: string
  after: string
  by: string
  at: string
  reason: string
  source: string
}

export interface BriefSignal {
  kind: 'delay' | 'change' | 'risk' | 'commitment'
  quote: string
  days: number | null
  activity: { id: string; code: string; name: string } | null
  documentId: string
  title: string
  citation: string
  docType: string
}

export interface BriefWhatIf {
  title: string
  text: string
  finishBefore: string | null
  finishAfter: string | null
  /** Calendar days the finish moves (+ = later) */
  days: number | null
}

export interface DailyBriefInput {
  /** The day the brief is for (YYYY-MM-DD) */
  today: string
  dataDate: string | null
  activities: Activity[]
  relationships: Pick<Relationship, 'predecessorId' | 'successorId'>[]
  forecastFinish: string | null
  /** The date the contract milestone (or the project) must meet, and where it comes from */
  required: { date: string; source: string | null; milestone: { code: string; name: string } | null } | null
  /** Forecast date of that milestone (the project finish when there is none) */
  milestoneForecast: string | null
  drivingPathIds: string[]
  register: RegisterItem[]
  signals: BriefSignal[]
  changes: BriefChange[]
  /** Forecast finish of the schedule as submitted, when RunF9 edits moved it */
  submittedFinish?: string | null
  whatIfs: BriefWhatIf[]
  logic: { looseEnds: number; outOfSequence: { text: string; reason: string }[]; proposals: { text: string; reason: string }[] }
  missingScope: string[]
  /** Since the previous update of the same project */
  sinceLastUpdate?: { version: string; finishMovedDays: number | null; added: number; deleted: number; logicChanges: number; durationChanges: number } | null
}

export interface DailyBrief {
  asOf: string
  dataDate: string | null
  /** Calendar days between the data date and the brief date; progress after the data date is not in the file */
  staleDays: number | null
  headline: { status: 'on_track' | 'behind' | 'ahead' | 'unknown'; daysBehind: number | null; forecast: string | null; required: string | null; requiredSource: string | null; milestone: string | null; text: string }
  yesterday: { date: string; completed: BriefRow[]; started: BriefRow[] }
  today: { finishing: BriefRow[]; starting: BriefRow[]; inProgress: BriefRow[]; inProgressCount: number }
  overdue: { shouldHaveFinished: BriefRow[]; shouldHaveStarted: BriefRow[]; finishCount: number; startCount: number }
  driving: { today: BriefRow | null; path: BriefRow[] }
  lookahead: { week: BriefRow[]; month: BriefRow[]; becomingCritical: BriefRow[]; milestones: BriefRow[] }
  risks: { text: string; source: 'schedule' | 'register' | 'correspondence'; severity: 'high' | 'medium' }[]
  issues: { text: string; source: 'schedule' | 'register' }[]
  changeItems: { id: string; kind: RegisterKind; title: string; impactDays: number | null; dueDate: string | null; overdue: boolean }[]
  changeImpactDays: number
  changed: { edits: BriefChange[]; finishMovedDays: number | null; sinceLastUpdate: DailyBriefInput['sinceLastUpdate'] }
  missing: { looseEnds: number; scope: string[]; proposals: { text: string; reason: string }[] }
  logic: { text: string; reason: string }[]
  whatIfs: BriefWhatIf[]
  signals: BriefSignal[]
  audiences: { pm: string[]; field: string[]; client: string[] }
}

const day = (v: string | null | undefined) => (v ? v.slice(0, 10) : null)
const addDays = (d: string, n: number) => new Date(Date.parse(d + 'T00:00:00Z') + n * 86_400_000).toISOString().slice(0, 10)
const diff = (a: string, b: string) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86_400_000)
const us = (d: string | null) => (d ? `${d.slice(5, 7)}/${d.slice(8, 10)}/${d.slice(0, 4)}` : '—')
const isWork = (a: Activity) => a.activityType === 'task' || a.activityType === 'milestone'
const done = (a: Activity) => a.status === 'complete' || !!a.actualFinish
const plural = (n: number, one: string, many = one + 's') => `${n} ${n === 1 ? one : many}`

/** The previous working day for "yesterday": Friday when the brief is for a Monday or a Sunday. */
export function previousWorkday(today: string): string {
  const dow = new Date(today + 'T00:00:00Z').getUTCDay()
  return addDays(today, dow === 1 ? -3 : dow === 0 ? -2 : -1)
}

const row = (a: Activity, date: string | null, extra: Partial<BriefRow> = {}): BriefRow => ({
  id: a.id, code: a.activityId, name: a.name, date, float: Number.isFinite(a.totalFloat) ? a.totalFloat : null,
  critical: !!a.isCritical, milestone: a.activityType === 'milestone', ...extra,
})
const byFloat = (x: BriefRow, y: BriefRow) => (x.float ?? 1e9) - (y.float ?? 1e9) || (x.date ?? '').localeCompare(y.date ?? '')
const label = (r: BriefRow) => `${r.code} ${r.name}`
const top = <T>(xs: T[]) => xs.slice(0, BRIEF_LIST_LIMIT)

export function buildDailyBrief(i: DailyBriefInput): DailyBrief {
  const today = i.today
  const yesterday = previousWorkday(today)
  const acts = i.activities.filter(isWork)
  const open = acts.filter(a => !done(a))
  const staleDays = i.dataDate ? Math.max(0, diff(day(i.dataDate)!, today)) : null

  // Yesterday (since the previous working day, so a Monday brief covers the weekend).
  const completed = acts.filter(a => { const f = day(a.actualFinish); return f && f >= yesterday && f <= today }).map(a => row(a, day(a.actualFinish)))
  const started = acts.filter(a => { const s = day(a.actualStart); return s && s >= yesterday && s <= today && !completed.some(c => c.id === a.id) }).map(a => row(a, day(a.actualStart)))

  // Today, per the schedule.
  const finishing = open.filter(a => day(a.earlyFinish) === today).map(a => row(a, today)).sort(byFloat)
  const starting = open.filter(a => !a.actualStart && day(a.earlyStart) === today).map(a => row(a, today)).sort(byFloat)
  const inProgressAll = open.filter(a => a.actualStart && a.activityType === 'task').map(a => row(a, day(a.earlyFinish))).sort(byFloat)

  // Should have happened by now but has no actual date.
  const lateFinish = open.filter(a => { const f = day(a.earlyFinish); return f && f < today }).map(a => row(a, day(a.earlyFinish), { daysLate: diff(day(a.earlyFinish)!, today) }))
    .sort((x, y) => Number(y.critical) - Number(x.critical) || (y.daysLate ?? 0) - (x.daysLate ?? 0))
  const lateStart = open.filter(a => { const s = day(a.earlyStart); return !a.actualStart && s && s < today && !(day(a.earlyFinish)! < today) }).map(a => row(a, day(a.earlyStart), { daysLate: diff(day(a.earlyStart)!, today) }))
    .sort((x, y) => Number(y.critical) - Number(x.critical) || (y.daysLate ?? 0) - (x.daysLate ?? 0))

  // What drives the finish: the open part of the driving path, in order.
  const byId = new Map(acts.map(a => [a.id, a]))
  const path = i.drivingPathIds.map(id => byId.get(id)).filter((a): a is Activity => !!a && !done(a)).map(a => row(a, day(a.earlyFinish)))
  const drivingToday = path.find(r => { const a = byId.get(r.id)!; return !!a.actualStart || (day(a.earlyStart) ?? '9') <= today }) ?? path[0] ?? null

  // Look ahead: critical and near-critical work in the next week and month, and float that is running out.
  const within = (d: string | null, from: string, days: number) => !!d && d > from && d <= addDays(from, days)
  const tight = (a: Activity) => a.isCritical || (Number.isFinite(a.totalFloat) && a.totalFloat <= NEAR_CRITICAL_DAYS)
  const week = open.filter(a => tight(a) && a.activityType === 'task' && (within(day(a.earlyStart), today, 7) || within(day(a.earlyFinish), today, 7)))
    .map(a => row(a, within(day(a.earlyStart), today, 7) && !a.actualStart ? day(a.earlyStart) : day(a.earlyFinish), { note: within(day(a.earlyStart), today, 7) && !a.actualStart ? 'starts' : 'finishes' })).sort(byFloat)
  const month = open.filter(a => tight(a) && a.activityType === 'task' && !week.some(w => w.id === a.id) && (within(day(a.earlyStart), today, 30) || within(day(a.earlyFinish), today, 30)))
    .map(a => row(a, within(day(a.earlyStart), today, 30) && !a.actualStart ? day(a.earlyStart) : day(a.earlyFinish), { note: within(day(a.earlyStart), today, 30) && !a.actualStart ? 'starts' : 'finishes' })).sort(byFloat)
  const becomingCritical = open.filter(a => a.activityType === 'task' && !a.isCritical && Number.isFinite(a.totalFloat) && a.totalFloat > 0 && a.totalFloat <= NEAR_CRITICAL_DAYS && (day(a.earlyStart) ?? '9') <= addDays(today, 30))
    .map(a => row(a, day(a.earlyStart), { note: `${a.totalFloat} work day${a.totalFloat === 1 ? '' : 's'} of float left` })).sort(byFloat)
  const milestones = open.filter(a => a.activityType === 'milestone' && (day(a.earlyFinish) ?? day(a.earlyStart) ?? '9') <= addDays(today, 30))
    .map(a => { const d = day(a.earlyFinish) ?? day(a.earlyStart); return row(a, d, d && d < today ? { daysLate: diff(d, today) } : {}) }).sort((x, y) => (x.date ?? '').localeCompare(y.date ?? ''))

  // Deadline.
  const req = i.required
  const fc = day(i.milestoneForecast) ?? day(i.forecastFinish)
  const daysBehind = req && fc ? diff(req.date, fc) : null
  const status: DailyBrief['headline']['status'] = daysBehind == null ? 'unknown' : daysBehind > 0 ? 'behind' : daysBehind < 0 ? 'ahead' : 'on_track'
  const target = req?.milestone ? `${req.milestone.code} ${req.milestone.name}` : 'the project finish'
  const headlineText = daysBehind == null
    ? (fc ? `Forecast finish ${us(fc)}. No required date is set, so RunF9 cannot say whether that is late; set the contract milestone on the Overview.` : 'The schedule has no calculated finish yet.')
    : daysBehind > 0 ? `Behind: ${target} is forecast ${us(fc)}, ${plural(daysBehind, 'calendar day')} after the required ${us(req!.date)}.`
      : daysBehind < 0 ? `Ahead: ${target} is forecast ${us(fc)}, ${plural(-daysBehind, 'calendar day')} before the required ${us(req!.date)}.`
        : `On time: ${target} is forecast ${us(fc)}, the required date.`

  // Register.
  const openItems = i.register.filter(r => r.status === 'open')
  const overdueItem = (r: RegisterItem) => !!r.dueDate && r.dueDate < today
  const changeKinds: RegisterKind[] = ['pco', 'change_request', 'change_order', 'amendment']
  const changeItems = openItems.filter(r => changeKinds.includes(r.kind))
    .map(r => ({ id: r.id, kind: r.kind, title: r.title, impactDays: r.impactDays ?? null, dueDate: r.dueDate ?? null, overdue: overdueItem(r) }))
  const changeImpactDays = changeItems.reduce((n, c) => n + Math.max(0, c.impactDays ?? 0), 0)

  // Today's risks: what could move the finish, most serious first.
  const risks: DailyBrief['risks'] = []
  const critLateStart = lateStart.filter(r => r.critical)
  const critLateFinish = lateFinish.filter(r => r.critical)
  if (critLateFinish.length) risks.push({ severity: 'high', source: 'schedule', text: `${plural(critLateFinish.length, 'critical activity', 'critical activities')} should have finished and ${critLateFinish.length === 1 ? 'has' : 'have'} no actual finish (worst: ${label(critLateFinish[0])}, ${plural(critLateFinish[0].daysLate ?? 0, 'day')} late). Each day pushes the finish.` })
  if (critLateStart.length) risks.push({ severity: 'high', source: 'schedule', text: `${plural(critLateStart.length, 'critical activity', 'critical activities')} should have started (first: ${label(critLateStart[0])}, due ${us(critLateStart[0].date)}).` })
  const negative = open.filter(a => Number.isFinite(a.totalFloat) && a.totalFloat < 0)
  if (negative.length) { const worst = negative.reduce((m, a) => (a.totalFloat < m.totalFloat ? a : m)); risks.push({ severity: 'high', source: 'schedule', text: `${plural(negative.length, 'open activity', 'open activities')} ${negative.length === 1 ? 'has' : 'have'} negative float (worst: ${worst.activityId} ${worst.name}, ${worst.totalFloat} work days). The required date cannot be met without recovery.` }) }
  if (drivingToday && week.length) risks.push({ severity: 'medium', source: 'schedule', text: `${plural(week.length, 'critical or near-critical activity', 'critical or near-critical activities')} ${week.length === 1 ? 'starts or finishes' : 'start or finish'} in the next 7 days; a miss on any of them reaches the finish.` })
  if (becomingCritical.length) risks.push({ severity: 'medium', source: 'schedule', text: `${plural(becomingCritical.length, 'activity', 'activities')} will become critical if ${becomingCritical.length === 1 ? 'it slips' : 'they slip'} ${NEAR_CRITICAL_DAYS} work days or less (closest: ${label(becomingCritical[0])}, ${becomingCritical[0].note}).` })
  for (const r of openItems.filter(x => x.kind === 'risk').slice(0, 6)) risks.push({ severity: overdueItem(r) || (r.impactDays ?? 0) >= 10 ? 'high' : 'medium', source: 'register', text: `${r.title}${r.impactDays ? ` (up to ${plural(r.impactDays, 'work day')})` : ''}${r.owner ? `, owner ${r.owner}` : ''}${r.dueDate ? `, due ${us(r.dueDate)}${overdueItem(r) ? ' (overdue)' : ''}` : ''}.` })
  for (const s of i.signals.filter(x => x.kind === 'delay' || x.kind === 'risk').slice(0, 3)) risks.push({ severity: 'medium', source: 'correspondence', text: `${s.title}: “${s.quote}”${s.activity ? ` (about ${s.activity.code} ${s.activity.name})` : ''} ${s.citation}` })

  // Today's issues: things already wrong.
  const issues: DailyBrief['issues'] = []
  if (staleDays != null && staleDays > 10) issues.push({ source: 'schedule', text: `Progress in this schedule is as of ${us(day(i.dataDate))}, ${plural(staleDays, 'day')} ago. Anything after that date is what the plan says should have happened, not what did. Upload an update or record progress.` })
  if (lateFinish.length) issues.push({ source: 'schedule', text: `${plural(lateFinish.length, 'activity', 'activities')} should have finished by now with no actual finish recorded.` })
  if (lateStart.length) issues.push({ source: 'schedule', text: `${plural(lateStart.length, 'activity', 'activities')} should have started by now with no actual start recorded.` })
  for (const r of openItems.filter(x => x.kind === 'issue').slice(0, 6)) issues.push({ source: 'register', text: `${r.title}${r.owner ? `, owner ${r.owner}` : ''}${r.dueDate ? `, due ${us(r.dueDate)}${overdueItem(r) ? ' (overdue)' : ''}` : ''}.` })
  const overdueChanges = changeItems.filter(c => c.overdue)
  if (overdueChanges.length) issues.push({ source: 'register', text: `${plural(overdueChanges.length, 'change item')} past ${overdueChanges.length === 1 ? 'its' : 'their'} due date (${overdueChanges.slice(0, 3).map(c => c.title).join('; ')}).` })

  const finishMovedDays = i.submittedFinish && i.forecastFinish && day(i.submittedFinish) !== day(i.forecastFinish) ? diff(day(i.submittedFinish)!, day(i.forecastFinish)!) : null

  // What each audience needs, in plain sentences.
  const pm: string[] = [headlineText]
  if (drivingToday) pm.push(`Driving the finish today: ${label(drivingToday)}${drivingToday.date ? `, forecast to finish ${us(drivingToday.date)}` : ''}. ${path.length > 1 ? `${plural(path.length, 'open activity', 'open activities')} on the driving path.` : ''}`.trim())
  if (lateFinish.length || lateStart.length) pm.push(`Overdue: ${plural(lateFinish.length, 'finish', 'finishes')} and ${plural(lateStart.length, 'start')} have no actual dates. ${critLateFinish.length + critLateStart.length ? `${critLateFinish.length + critLateStart.length} of them are critical.` : 'None is critical yet.'}`)
  if (changeItems.length) pm.push(`${plural(changeItems.length, 'open change item')} (PCOs, change requests, change orders, amendments)${changeImpactDays ? ` carrying up to ${plural(changeImpactDays, 'work day')} of schedule impact` : ''}; decide or request time before the work is affected.`)
  if (i.whatIfs[0]) pm.push(`What-if: ${i.whatIfs[0].text}`)
  if (becomingCritical.length) pm.push(`Watch: ${label(becomingCritical[0])} has ${becomingCritical[0].note}.`)
  if (i.changes.length) pm.push(`${plural(i.changes.length, 'change')} made to the schedule in RunF9 in the last 7 days${finishMovedDays ? `; with all RunF9 edits the finish is ${plural(Math.abs(finishMovedDays), 'day')} ${finishMovedDays > 0 ? 'later' : 'earlier'} than as submitted` : ''}.`)

  const field: string[] = []
  field.push(starting.length ? `Starting today: ${starting.slice(0, 6).map(label).join('; ')}${starting.length > 6 ? `; and ${starting.length - 6} more` : ''}.` : 'Nothing new is scheduled to start today.')
  field.push(finishing.length ? `Must finish today: ${finishing.slice(0, 6).map(label).join('; ')}${finishing.length > 6 ? `; and ${finishing.length - 6} more` : ''}.` : 'Nothing is scheduled to finish today.')
  if (inProgressAll.length) field.push(`Under way: ${inProgressAll.slice(0, 5).map(r => `${label(r)}${r.date ? ` (finish ${us(r.date)})` : ''}`).join('; ')}${inProgressAll.length > 5 ? `; and ${inProgressAll.length - 5} more` : ''}.`)
  if (drivingToday) field.push(`Do not let this slip: ${label(drivingToday)}. It is driving the project finish, so every day lost here is a day lost at the end.`)
  if (lateStart.length) field.push(`Should already be started: ${lateStart.slice(0, 4).map(label).join('; ')}${lateStart.length > 4 ? `; and ${lateStart.length - 4} more` : ''}. Report actual start dates.`)
  const tomorrow = open.filter(a => !a.actualStart && within(day(a.earlyStart), today, 3)).map(a => row(a, day(a.earlyStart))).sort((x, y) => (x.date ?? '').localeCompare(y.date ?? ''))
  if (tomorrow.length) field.push(`Coming in the next 3 days: ${tomorrow.slice(0, 5).map(r => `${label(r)} (${us(r.date)})`).join('; ')}${tomorrow.length > 5 ? `; and ${tomorrow.length - 5} more` : ''}. Confirm crews, materials and access.`)

  const client: string[] = [daysBehind == null ? (fc ? `The current forecast finish is ${us(fc)}.` : 'The forecast finish is not yet calculated.') : daysBehind > 0 ? `${cap(target)} is currently forecast ${us(fc)}, ${plural(daysBehind, 'calendar day')} later than the required ${us(req!.date)}.` : `${cap(target)} is forecast ${us(fc)}, ${daysBehind === 0 ? 'on' : `${plural(-daysBehind, 'calendar day')} ahead of`} the required ${us(req!.date)}.`]
  const pct = acts.length ? Math.round((acts.filter(done).length / acts.length) * 100) : 0
  client.push(`${pct}% of activities are complete (${acts.filter(done).length} of ${acts.length}).`)
  const nextMs = milestones.filter(m => (m.date ?? '') >= today).slice(0, 4)
  if (nextMs.length) client.push(`Milestones in the next 30 days: ${nextMs.map(m => `${m.name} (${us(m.date)})`).join('; ')}.`)
  if (changeItems.length) client.push(`${plural(changeItems.length, 'change item')} ${changeItems.length === 1 ? 'is' : 'are'} open${changeImpactDays ? `, with up to ${plural(changeImpactDays, 'work day')} of possible schedule impact under review` : ''}.`)
  if (drivingToday) client.push(`The work currently setting the finish date is ${drivingToday.name}.`)

  return {
    asOf: today, dataDate: day(i.dataDate), staleDays,
    headline: { status, daysBehind, forecast: fc, required: req?.date ?? null, requiredSource: req?.source ?? null, milestone: req?.milestone ? target : null, text: headlineText },
    yesterday: { date: yesterday, completed: top(completed), started: top(started) },
    today: { finishing: top(finishing), starting: top(starting), inProgress: top(inProgressAll), inProgressCount: inProgressAll.length },
    overdue: { shouldHaveFinished: top(lateFinish), shouldHaveStarted: top(lateStart), finishCount: lateFinish.length, startCount: lateStart.length },
    driving: { today: drivingToday, path: top(path) },
    lookahead: { week: top(week), month: top(month), becomingCritical: top(becomingCritical), milestones: top(milestones) },
    risks, issues, changeItems, changeImpactDays,
    changed: { edits: i.changes, finishMovedDays, sinceLastUpdate: i.sinceLastUpdate ?? null },
    missing: { looseEnds: i.logic.looseEnds, scope: i.missingScope, proposals: i.logic.proposals.slice(0, 6) },
    logic: i.logic.outOfSequence.slice(0, 6),
    whatIfs: i.whatIfs,
    signals: i.signals,
    audiences: { pm, field, client },
  }
}

const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1)

/* ─── Scope that a project of this type normally has ─────────────────────── */

export interface ScopeCheck { label: string; words: RegExp }
export const BUILDING_SCOPE: ScopeCheck[] = [
  { label: 'Permits / approvals', words: /\bpermit|approval|\bAHJ\b|entitlement/i },
  { label: 'Submittals and procurement of long-lead items', words: /submittal|procure|fabricat|deliver|long[- ]lead|\bPO\b|purchase/i },
  { label: 'Foundations', words: /foundation|footing|pile|caisson|mat slab|\bSOG\b|slab on grade/i },
  { label: 'Structure', words: /steel|structur|framing|precast|tilt|concrete (frame|deck|column)|erect/i },
  { label: 'Roofing / building enclosure', words: /roof|enclosure|envelope|curtain ?wall|glazing|dry[- ]?in|weather ?tight/i },
  { label: 'Mechanical, electrical and plumbing rough-in', words: /\bMEP\b|mechanical|electrical|plumbing|HVAC|duct|conduit|rough/i },
  { label: 'Permanent power / energization', words: /permanent power|energi[sz]|utility power|switchgear|transformer|service entrance/i },
  { label: 'Commissioning / testing', words: /commission|\bCx\b|start[- ]?up|testing|\bTAB\b|functional test/i },
  { label: 'Inspections / certificate of occupancy', words: /inspection|certificate of occupancy|\bTCO\b|\bCO\b|final inspection|fire marshal/i },
  { label: 'Punch list and closeout', words: /punch|close[- ]?out|turnover|as[- ]built|O&M/i },
]
export const DATA_CENTER_SCOPE: ScopeCheck[] = [
  { label: 'Utility interconnect / substation', words: /substation|interconnect|utility (power|service|feed)|grid|\bMV\b|medium voltage/i },
  { label: 'Generators', words: /generator|genset|\bgen\b/i },
  { label: 'UPS / batteries', words: /\bUPS\b|batter|uninterruptible/i },
  { label: 'Switchgear / transformers / PDUs', words: /switchgear|transformer|\bPDU\b|\bRPP\b|busway|bus duct|switchboard/i },
  { label: 'Cooling plant (chillers, CRAH/CRAC, cooling towers)', words: /chiller|CRAH|CRAC|cooling tower|\bCDU\b|liquid cooling|fan wall|chilled water/i },
  { label: 'Fire detection and suppression', words: /fire (alarm|suppress|protect|detect)|sprinkler|pre[- ]?action|VESDA|clean agent/i },
  { label: 'Data hall fit-out (racks, containment, cable tray)', words: /data hall|white space|rack|containment|cable tray|raised floor/i },
  { label: 'Network / fiber (MMR, carrier)', words: /fiber|meet[- ]me|\bMMR\b|carrier|network|telecom/i },
  { label: 'Controls (BMS / EPMS)', words: /\bBMS\b|\bEPMS\b|\bBAS\b|controls|SCADA/i },
  { label: 'Commissioning levels (L1–L5) and integrated systems test', words: /\bL[1-5]\b|level [1-5]|integrated systems? test|\bIST\b|factory (acceptance|witness)|\bFAT\b|\bFWT\b|site acceptance|\bSAT\b/i },
  { label: 'Ready for service / customer turnover', words: /ready for service|\bRFS\b|turnover|handover|beneficial occupancy/i },
]

/** Kinds of work a project of this type normally has that no activity name or WBS mentions. Only for schedules large enough to expect them. */
export function missingScope(activities: Pick<Activity, 'name' | 'wbs' | 'activityType'>[], projectType: string | null | undefined): string[] {
  const work = activities.filter(a => a.activityType === 'task' || a.activityType === 'milestone')
  if (work.length < 25) return []
  const dc = projectType === 'data_center' || work.filter(a => /data ?(center|hall)|\bUPS\b|generator|CRAH|chiller|\bIST\b/i.test(`${a.name} ${a.wbs ?? ''}`)).length >= 3
  const text = work.map(a => `${a.name} ${a.wbs ?? ''}`).join('\n')
  const civil = (CIVIL_PROJECT_TYPES as readonly string[]).includes(projectType ?? '')
  return [...(civil ? [] : BUILDING_SCOPE), ...(dc ? DATA_CENTER_SCOPE : [])].filter(c => !c.words.test(text)).map(c => c.label)
}
